def cash(x):return f'${D(str(x)):,.2f}'
def pct(x):return f'{100*x:.2f}%'
class ReadableText(HTMLParser):
 def __init__(self):super().__init__(convert_charrefs=False);self.output=[];self.in_style=False
 def handle_decl(self,value):self.output.append('<!'+value+'>')
 def handle_starttag(self,tag,attrs):self.output.append(self.get_starttag_text());self.in_style=self.in_style or tag=='style'
 def handle_endtag(self,tag):self.output.append('</'+tag+'>');self.in_style=False if tag=='style' else self.in_style
 def handle_data(self,value):
  if not self.in_style:
   value=re.sub(r'(?<=[A-Za-z])(?=[0-9$])',' ',value)
   value=re.sub(r'(?<=[0-9%¢])(?=[A-Za-z])',' ',value)
  self.output.append(value)
 def handle_entityref(self,name):self.output.append('&'+name+';')
 def handle_charref(self,name):self.output.append('&#'+name+';')
def readable(value):
 parser=ReadableText();parser.feed(value);return ''.join(parser.output)
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+E(str(v))+'</th>' for v in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+E(str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
